params.command:
$ErrorActionPreference='Stop'
$root=Join-Path $env:TEMP 'mhw-updater-e2e-harness-local-build'
if(Test-Path $root){Remove-Item -Recurse -Force $root}
git clone --no-tags --branch agent/updater-installed-e2e-20260929-manager https://github.com/fengie/mhw-mods.git $root
if($LASTEXITCODE -ne 0){throw 'clone failed'}
dotnet restore (Join-Path $root 'tools\MhwModManager.UpdaterE2E\MhwModManager.UpdaterE2E.csproj') --source (Join-Path $root 'data') --ignore-failed-sources -p:NuGetAudit=false
if($LASTEXITCODE -ne 0){throw 'restore failed'}
dotnet build (Join-Path $root 'tools\MhwModManager.UpdaterE2E\MhwModManager.UpdaterE2E.csproj') -c Release --no-restore -p:NuGetAudit=false
if($LASTEXITCODE -ne 0){throw 'build failed'}
git -C $root status --short
Write-Output ('HEAD='+(git -C $root rev-parse HEAD))
